{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_387df46b63bf50492746aa9e", "claim_ids": ["claim_a20faa1e84a70dab16bff1fb", "claim_eb751fb4a50270c700539d20"], "query_ids": ["q_217"], "claims": [{"claim_id": "claim_a20faa1e84a70dab16bff1fb", "quote": "The Court of Justice of the European Union (hereinafter “CJEU”), in a judgment dated November 19, 2020 (case C 775/19, 5th Avenue), interpreted the conditions for reintegrating, in the customs value of imported goods, royalties paid by a buyer in exchange for the right to exclusively distribute these goods within the territory of the European union.", "url": "https://dscustomsandtrade.com/tag/customs-valuation", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Customs Valuation Agreement", "legal_authority": "Article 8.1.c of the Customs Valuation Agreement", "announcement_date": "November 19, 2020", "reported_policy_status": "judgment dated November 19, 2020 (case C 775/19, 5th Avenue)"}}, {"claim_id": "claim_eb751fb4a50270c700539d20", "quote": "The opinion concludes that the entire royalty has been reinstated in the value of the input, since the conditions of Article 8.1.c of the Customs Valuation Agreement (i.e., the relationship of the royalty with the input and its payment as a condition of the sale export of the input) are met.", "url": "https://dscustomsandtrade.com/tag/customs-valuation", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Customs Valuation Agreement", "legal_authority": "Article 8.1.c of the Customs Valuation Agreement"}}]}, {"pair_id": "conflict_4d03ee5956fc703300539c15", "claim_ids": ["claim_3f7c9285e050f98e1e2481f9", "claim_b2e169216fa3901d5abe61e0"], "query_ids": ["q_219"], "claims": [{"claim_id": "claim_3f7c9285e050f98e1e2481f9", "quote": "Ms. Brown said 43 Georgia companies supporting 14,442 jobs in the state — from Yamaha Motor Manufacturing in Newnan to Kubota in Gainesville and Southwire in Villa Rica — have saved an average of $1 million after joining the zone.", "url": "https://www.globalatlanta.com/strategies-for-tariff-relief-how-georgia-companies-can-avoid-trade-war-paralysis", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Kubota"}}, {"claim_id": "claim_b2e169216fa3901d5abe61e0", "quote": "Ms. Brown said 43 Georgia companies supporting 14,442 jobs in the state — from Yamaha Motor Manufacturing in Newnan to Kubota in Gainesville and Southwire in Villa Rica — have saved an average of $1 million after joining the zone.", "url": "https://www.globalatlanta.com/strategies-for-tariff-relief-how-georgia-companies-can-avoid-trade-war-paralysis", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Southwire"}}]}, {"pair_id": "conflict_4180e1e1a409ea40d60859ad", "claim_ids": ["claim_3f7c9285e050f98e1e2481f9", "claim_dcc35c78e8358bc846d87723"], "query_ids": ["q_219"], "claims": [{"claim_id": "claim_3f7c9285e050f98e1e2481f9", "quote": "Ms. Brown said 43 Georgia companies supporting 14,442 jobs in the state — from Yamaha Motor Manufacturing in Newnan to Kubota in Gainesville and Southwire in Villa Rica — have saved an average of $1 million after joining the zone.", "url": "https://www.globalatlanta.com/strategies-for-tariff-relief-how-georgia-companies-can-avoid-trade-war-paralysis", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Kubota"}}, {"claim_id": "claim_dcc35c78e8358bc846d87723", "quote": "Ms. Brown said 43 Georgia companies supporting 14,442 jobs in the state — from Yamaha Motor Manufacturing in Newnan to Kubota in Gainesville and Southwire in Villa Rica — have saved an average of $1 million after joining the zone.", "url": "https://www.globalatlanta.com/strategies-for-tariff-relief-how-georgia-companies-can-avoid-trade-war-paralysis", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Yamaha Motor Manufacturing"}}]}, {"pair_id": "conflict_aefaee1a244283d05356857d", "claim_ids": ["claim_8592777e804c179fd61395ec", "claim_fadfaec0d508c64e74e160e8"], "query_ids": ["q_221"], "claims": [{"claim_id": "claim_8592777e804c179fd61395ec", "quote": "The 10% tariffs imposed under Section 122 of the Trade Act of 1974…", "url": "https://www.naftz.org/ftz-trade-and-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 122 of the Trade Act of 1974", "duty_rate": "10%"}}, {"claim_id": "claim_fadfaec0d508c64e74e160e8", "quote": "The Supreme Court struck down tariffs imposed under the International Emergency Economic Powers Act (IEEPA) in February 2026, but the administration continued pursuing battery-related trade barriers through other legal authorities including Section 232 investigations, while maintaining existing measures including a 10 percent import surcharge under Section 122.", "url": "https://www.totexmfg.com/battery-pack-tariffs-oem-2026", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "10 percent import surcharge", "legal_authority": "Section 122", "duty_rate": "10 percent"}}]}, {"pair_id": "conflict_b89046341baaeb1d075992cc", "claim_ids": ["claim_1cdffd44eda1030a5a2e6c22", "claim_e0356b40b3734bcd80a59a3c"], "query_ids": ["q_222"], "claims": [{"claim_id": "claim_1cdffd44eda1030a5a2e6c22", "quote": "Bonded warehouses allow importers to defer duty payments for up to five years, freeing up capital that would otherwise be tied up in customs duties.", "url": "https://geodis.com/us-en/resources/blog/warehousing-and-value-added-logistics-expertise/bonded-warehouses-manage-us-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "bonded warehouse", "duty_rate": "defer duty payments for up to five years"}}, {"claim_id": "claim_e0356b40b3734bcd80a59a3c", "quote": "A customs bonded warehouse is a secured facility authorized by U.S. Customs and Border Protection where imported dutiable merchandise may be stored for up to five years from the date of importation without immediate payment of duties.", "url": "https://geodis.com/us-en/resources/blog/warehousing-and-value-added-logistics-expertise/bonded-warehouses-manage-us-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "customs bonded warehouse", "legal_authority": "U.S. Customs and Border Protection"}}]}, {"pair_id": "conflict_aaf04e90646c7f36e04fa779", "claim_ids": ["claim_692b636f9baed45fb8020c5d", "claim_7b02e8c7f7d196a24bd6f974"], "query_ids": ["q_223"], "claims": [{"claim_id": "claim_692b636f9baed45fb8020c5d", "quote": "Duty drawback will not be available for the 25% tariff imposed pursuant to the Proclamation.", "url": "https://www.troutman.com/insights/new-section-232-tariffs-on-automobiles-and-automotive-parts", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "duty_rate": "25%"}}, {"claim_id": "claim_7b02e8c7f7d196a24bd6f974", "quote": "No drawback shall be available with respect to the duties imposed pursuant to this proclamation.", "url": "https://www.whitehouse.gov/presidential-actions/2025/03/adjusting-imports-of-automobiles-and-autombile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "this proclamation"}}]}, {"pair_id": "conflict_4d62f6f7c5f7c69afcba8632", "claim_ids": ["claim_17d9d5acac764e7c3132b929", "claim_ca3c11a8b4c09c26a4d3badc"], "query_ids": ["q_226"], "claims": [{"claim_id": "claim_17d9d5acac764e7c3132b929", "quote": "The IEEPA reciprocal tariffs that excluded US content were vacated by the Supreme Court on February 20, 2026, but 9802.00.80 is a statutory provision that does not depend on an executive action a court can undo", "url": "https://gingercontrol.com/blog/9802-9801-us-content-goods-returned-duty-program", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "9802.00.80", "announcement_date": "February 20, 2026", "reported_policy_status": "vacated"}}, {"claim_id": "claim_ca3c11a8b4c09c26a4d3badc", "quote": "The IEEPA-based \"reciprocal\" tariffs imposed in 2025 were struck down by the Supreme Court in Learning Resources, Inc. v. Trump on February 20, 2026; CBP ceased collecting IEEPA deposits on February 24, 2026", "url": "https://gingercontrol.com/blog/9802-9801-us-content-goods-returned-duty-program", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"legal_authority": "Supreme Court in Learning Resources, Inc. v. Trump", "expiration_date": "February 20, 2026", "reported_policy_status": "Struck down"}}]}, {"pair_id": "conflict_a8d4e57b1dc625aba3b383d6", "claim_ids": ["claim_786ce385316cee5582e6ea53", "claim_976c5a757176b7c658b5e0dd"], "query_ids": ["q_226"], "claims": [{"claim_id": "claim_786ce385316cee5582e6ea53", "quote": "Section 232 steel and aluminum at 50% (effective February 1, 2026)", "url": "https://gingercontrol.com/blog/9802-9801-us-content-goods-returned-duty-program", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 Tariffs on Steel and Aluminum", "duty_rate": "50%", "effective_date": "February 1, 2026"}}, {"claim_id": "claim_976c5a757176b7c658b5e0dd", "quote": "Section 232 duties, raised to 50% on steel and aluminum effective February 1, 2026, are unaffected by any court ruling and still apply.", "url": "https://gingercontrol.com/blog/9802-9801-us-content-goods-returned-duty-program", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "duty_rate": "50%", "effective_date": "February 1, 2026"}}]}, {"pair_id": "conflict_cfa905c3764dee5887185b3b", "claim_ids": ["claim_0289f9e8b07a82c1bd107479", "claim_3e251d4aa883695c03265dd0"], "query_ids": ["q_228"], "claims": [{"claim_id": "claim_0289f9e8b07a82c1bd107479", "quote": "CBP does not charge any fees for processing tariff refunds. If you are asked to pay a fee or provide financial information by a party claiming to be CBP, it is a scam and you should report it to the Traderelations@cbp.dhs.gov mailbox.", "url": "https://www.cbp.gov/trade/programs-administration/trade-remedies/ieepa-duty-refunds", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {}}, {"claim_id": "claim_3e251d4aa883695c03265dd0", "quote": "The total refund that is deposited in your bank account for a specific entry includes the duties being refunded for that entry, plus applicable interest, which may be netted with additional duties that may be owed for the entry as determined upon liquidation or reliquidation", "url": "https://www.cbp.gov/trade/programs-administration/trade-remedies/ieepa-duty-refunds", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "CAPE", "duty_rate": "10%"}}]}, {"pair_id": "conflict_9603552150e821a49ff2eafd", "claim_ids": ["claim_0e137a8c4bae7f244636f0b5", "claim_d0a08e84d91003b681287e73"], "query_ids": ["q_228"], "claims": [{"claim_id": "claim_0e137a8c4bae7f244636f0b5", "quote": "The U.S. Court of International Trade (CIT) has indicated that CBP protest procedures under 19 C.F.R. part 174 are likely not a valid refund mechanism for liquidated entries made before the Supreme Court found IEEPA tariffs to be unlawful.", "url": "https://www.buchalter.com/insights/after-learning-resources-v-trump-strategic-paths-to-recovering-unliquidated-ieepa-tariffs-through-post-summary-corrections", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"legal_authority": "19 C.F.R. part 174", "reported_policy_status": "likely not a valid refund mechanism for liquidated entries made before the Supreme Court found IEEPA tariffs to be unlawful"}}, {"claim_id": "claim_d0a08e84d91003b681287e73", "quote": "For entries within the CAPE Phase 1 scope, most IEEPA refunds flow through the streamlined CAPE system. For everything outside that window, the legal pathway is a formal CBP protest under 19 U.S.C. § 1514.", "url": "https://ayarlaw.com/tariff-refund-resources/cbp-protest-tariff-refund", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "CAPE Phase 1", "legal_authority": "19 U.S.C. § 1514"}}]}]}

